/* Local editor: product data in, the same runtime in preview and MAX. */
'use strict';
const $=s=>document.querySelector(s), E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const S={config:null,revision:0,published:0,section:'scenarios',branch:'all',selected:'welcome',view:'cascade',editing:false,back:[],zoom:1,fit:false,dirty:false,chat:'',busy:false,warnings:[],model:'',evalResults:[]};
const nav=[['scenarios','⌘','Сценарии'],['materials','▤','Материалы'],['rules','◇','Правила и LLM'],['templates','☷','Служебные тексты'],['evaluations','◉','Эвалы'],['search','⌕','Проверка поиска'],['history','↶','Версии'],['events','▥','События']];
const kinds={message:'Сообщение',question:'Вопрос',action:'Действие сервиса',answer:'Ответ LLM'};
const actions={search:'Поиск вакансий',search_more:'Следующие вакансии',search_change:'Изменить поиск',search_miss:'Ничего не подошло',checklist:'Чек-лист',reminders:'Список напоминаний',reminder_new:'Создать напоминание',reminder_tasks:'Напомнить о пункте',social:'Реестр социальной помощи'};
const roles={child:'Ребёнок / выпускник',parent:'Родитель / опекун',candidate:'Будущий родитель'};
const ops={eq:'равно',ne:'не равно',lt:'меньше',lte:'не больше',gt:'больше',gte:'не меньше',contains:'содержит',known:'известно'};
function options(dict,value,empty=false){return (empty?'<option value="">Без перехода</option>':'')+Object.entries(dict).map(([k,v])=>`<option value="${E(k)}" ${String(value)===k?'selected':''}>${E(v)}</option>`).join('')}
function fieldNames(){return {query:'Профессия',city:'Город поиска работы',age:'Возраст ребёнка / соискателя',experience:'Опыт работы, лет',salary:'Желаемая зарплата',home_city:'Город проживания',help_city:'Город срочной помощи',study:'Учёба',family_status:'Семейная ситуация',role:'Роль пользователя',housing:'Нужно проживание',schedule:'График работы',education_level:'Образование соискателя',employment:'Тип занятости',...Object.fromEntries(S.config.nodes.filter(n=>n.field&&!['query','city','age','experience','salary','home_city','help_city','study','family_status'].includes(n.field)).map(n=>[n.field,n.title]))}}
function targets(value,empty=true){return options(Object.fromEntries(S.config.nodes.map(n=>[n.id,`${S.config.branches.find(b=>b.id===n.branch)?.title||''} · ${n.title}`])),value,empty)}
function field(label,html,hint=''){return `<label class="field"><span>${E(label)}</span>${html}${hint?`<span class="hint">${E(hint)}</span>`:''}</label>`}
function input(value,attrs=''){return `<input value="${E(value)}" ${attrs}>`}
function area(value,attrs=''){return `<textarea ${attrs}>${E(value)}</textarea>`}
function button(text,action,attrs='',style='secondary'){return `<button type="button" class="button ${style}" data-action="${action}" ${attrs}>${text}</button>`}
function check(label,checked,attrs){return `<label class="check-row"><input type="checkbox" ${checked?'checked':''} ${attrs}>${E(label)}</label>`}
function pageHead(title,subtitle,extra=''){return `<div class="page-title"><div><h1>${E(title)}</h1><p>${E(subtitle)}</p></div>${extra}</div>`}
function notify(text,error=false){$('#notice').hidden=false;$('#notice').textContent=text;$('#notice').classList.toggle('error',error)}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
async function api(path,body,method='POST'){const r=await fetch('/api/'+path,{method:body===undefined?'GET':method,headers:body===undefined?{}:{'Content-Type':'application/json','X-Editor-Request':'local'},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(!r.ok)throw Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));return data}
async function safe(fn){try{return await fn()}catch(e){notify(e.message,true);return null}}
function changed(){S.dirty=true;$('#save-status').textContent='Есть несохранённые изменения';$('#save-status').style.color='#a36f39'}
function status(){ $('#save-status').textContent=`Черновик ${S.revision} · сохранён`;$('#save-status').style.color='';$('#live-version').textContent=`В MAX: версия ${S.published}` }
async function load(){const data=await api('state');S.config=data.config;S.revision=data.revision;S.published=data.published_id;S.warnings=data.warnings;S.model=data.model;S.dirty=false;status();render()}
async function save(){if(!S.dirty)return;const result=await api('draft',{config:S.config,revision:S.revision},'PUT');S.revision=result.revision;S.dirty=false;status();toast('Черновик сохранён. MAX пока без изменений.');S.chat=''}
function render(){ $('#navigation').innerHTML=nav.map(([id,icon,name],i)=>`${i===4?'<div class="nav-heading">ПРОВЕРКА И КОНТРОЛЬ</div>':''}<button data-action="nav" data-id="${id}" class="${S.section===id?'active':''}"><span class="nav-symbol">${icon}</span><span class="nav-text">${name}</span></button>`).join('');({scenarios:renderScenarios,materials:renderMaterials,rules:renderRules,templates:renderTemplates,evaluations:renderEvals,search:renderSearch,history:renderHistory,events:renderEvents}[S.section])() }
function currentNode(){return S.config.nodes.find(n=>n.id===S.selected)}
function renderScenarios(){
 let branch=S.branch==='all'?{id:'all',title:'Весь сценарий',roles:[],status:'ready'}:S.config.branches.find(b=>b.id===S.branch)||S.config.branches[0];S.branch=branch.id;
 let nodes=S.config.nodes.filter(n=>branch.id==='all'||n.branch===branch.id);if(!nodes.some(n=>n.id===S.selected))S.selected=nodes[0]?.id;
 $('#main').innerHTML=`<div class="page">${pageHead('Всё начинается с диалога','Ветки, слова и следующий шаг — теперь под вашим контролем.',button('+ Новая ветка','new-branch','','lime'))}<div class="branch-tabs" aria-label="Выбрать ветку">${[{id:'all',title:'Весь сценарий'},...S.config.branches].map(b=>`<button data-action="choose-branch" data-id="${E(b.id)}" class="${b.id===S.branch?'active':''}">${E(b.title)}</button>`).join('')}</div><div class="scenario-toolbar">${button('← Назад','branch-back',S.back.length?'':'disabled')}<select id="branch-select" class="branch-select" aria-label="Ветка">${options({all:'Весь сценарий',...Object.fromEntries(S.config.branches.map(b=>[b.id,b.title]))},branch.id)}</select><span class="chip ${branch.status==='ready'?'':'orange'}">${branch.status==='ready'?'● Готово':'○ Не готово'}</span><button class="text-button" ${S.branch==='all'?'disabled':''} data-action="branch-settings">Настроить ветку</button><div class="segmented"><button data-action="view" data-id="cascade" class="${S.view==='cascade'?'active':''}">Каскад</button><button data-action="view" data-id="map" class="${S.view==='map'?'active':''}">Карта</button><button data-action="view" data-id="list" class="${S.view==='list'?'active':''}">Шаги</button></div></div><div class="workbench ${S.view==='cascade'?'cascade-workbench':''} ${S.editing?'editing':''}"><section class="canvas" aria-label="Сценарий ветки"><div class="canvas-top"><span>${nodes.length} шагов · ${E(rolesView(branch.roles))}</span><button class="text-button" ${S.branch==='all'?'disabled':''} data-action="new-node">+ Добавить шаг</button></div><div id="canvas-content"></div></section><aside class="inspector" id="inspector"></aside></div></div>`;
 renderCanvas();renderInspector();
}
function rolesView(list){return !list?.length||list.length===3?'все роли':list.map(r=>roles[r]||r).join(', ')}
function outgoing(n){return [...(n.next?[{target:n.next,label:'далее'}]:[]),...(n.buttons||[]).filter(b=>b.target).map(b=>({target:b.target,label:b.label})),...(n.routes||[]).map(r=>({target:r.target,label:`если ${r.field} ${ops[r.op]} ${r.value}`}))]}
function conditionText(items){return (items||[]).map(r=>`${fieldNames()[r.field]||r.field} ${ops[r.op]||r.op} ${r.value??''}`).join(' и ')}
function navigateBranch(id){
 if(id!==S.branch){const v=$('.cascade-viewport');S.back.push({branch:S.branch,selected:S.selected,zoom:S.zoom,left:v?.scrollLeft||0,top:v?.scrollTop||0});S.branch=id;S.fit=false;S.zoom=1}
 S.editing=false;if(id==='all')S.view='cascade';renderScenarios();
}
function applyZoom(fit=false){
 const v=$('.cascade-viewport'),t=$('.cascade-tree');if(!v||!t)return;
 if(fit){t.style.zoom=1;S.zoom=Math.min(1,(v.clientWidth-30)/t.offsetWidth,(v.clientHeight-30)/t.offsetHeight)}
 t.style.zoom=S.zoom;$('#zoom-level').textContent=Math.round(S.zoom*100)+'%';
 if(fit){v.scrollLeft=0;v.scrollTop=0}
 else if(!v.dataset.positioned){const first=t.querySelector('.cascade-node');if(first){const r=first.getBoundingClientRect(),vr=v.getBoundingClientRect();v.scrollLeft=Math.max(0,r.left-vr.left+r.width/2-v.clientWidth/2);v.scrollTop=0}}
 v.dataset.positioned='true';
}
function changeZoom(value,x,y){
 const v=$('.cascade-viewport');if(!v)return;const old=S.zoom;
 x??=v.clientWidth/2;y??=v.clientHeight/2;const left=(v.scrollLeft+x)/old,top=(v.scrollTop+y)/old;
 S.fit=false;S.zoom=Math.max(.03,Math.min(2,value));applyZoom();v.scrollLeft=left*S.zoom-x;v.scrollTop=top*S.zoom-y;
}
function focusNode(id){changeZoom(1);const n=document.getElementById('cascade-'+id);if(n){n.scrollIntoView({block:'nearest',inline:'center'});document.querySelectorAll('.cascade-highlight').forEach(x=>x.classList.remove('cascade-highlight'));n.classList.add('cascade-highlight')}}
document.addEventListener('wheel',e=>{const v=e.target.closest('.cascade-viewport');if(v&&e.ctrlKey){e.preventDefault();const r=v.getBoundingClientRect();changeZoom(S.zoom*(e.deltaY<0?1.12:1/1.12),e.clientX-r.left,e.clientY-r.top)}},{passive:false});
window.addEventListener('resize',()=>{if(S.fit)applyZoom(true)});
function renderCascade(nodes,branch,contentOnly=false){
 const seen=new Set(), all=new Map(S.config.nodes.map(n=>[n.id,n]));
 function reference(id,label){const n=all.get(id);return `<button class="cascade-reference" data-action="cascade-jump" data-id="${E(id)}">${E(label)} → ${E(n?.title||'Шаг не найден')}</button>`}
 function walk(id){
  const n=all.get(id);if(!n)return '<p>Шаг не найден</p>';
  if(n.branch!==branch.id)return reference(id,`Перейти в ветку «${S.config.branches.find(b=>b.id===n.branch)?.title||''}»`);
  if(seen.has(id))return reference(id,'К показанному шагу');
  seen.add(id);
  const edges=[...(n.next?[{target:n.next,label:n.kind==='question'?'После ответа пользователя':'Далее'}]:[]),...(n.routes||[]).map(r=>({target:r.target,label:'Если '+conditionText([r])})),...(n.buttons||[]).map(b=>({target:b.target,url:b.url,label:'Кнопка «'+b.label+'»',conditions:b.conditions}))];
  return `<div class="cascade-cluster"><article class="cascade-node" id="cascade-${E(n.id)}"><div class="cascade-heading"><div><small>${E(kinds[n.kind])}${n.id===branch.entry?' · НАЧАЛО ВЕТКИ':''}</small><h3>${E(n.title)}</h3></div><div class="cascade-node-tools">${button('Приблизить','focus-node',`data-id="${E(n.id)}"`)}${button('Редактировать','select-node',`data-id="${E(n.id)}"`)}</div></div>${n.conditions?.length?`<div class="cascade-condition">Показывать, если ${E(conditionText(n.conditions))}</div>`:''}${n.text?`<div class="cascade-text">${E(n.text)}</div>`:''}${n.adult_text?`<details><summary>Текст для взрослого</summary><div class="cascade-text">${E(n.adult_text)}</div></details>`:''}${n.kind==='question'?`<p class="cascade-note">Ответ: ${E(fieldNames()[n.field]||n.title)} · ${n.required?'обязательный вопрос':'можно пропустить'}</p>`:''}${n.kind==='action'?`<div class="cascade-service">Действие: ${E(actions[n.action]||n.action)}. Результат зависит от данных пользователя и сервиса.${['search','search_more'].includes(n.action)?' Бот показывает карточки вакансий или сообщение об отсутствии результатов. Динамические сообщения и кнопки доступны в разделе «Служебные тексты».':''}</div>`:''}${n.kind==='answer'?'<div class="cascade-service">LLM формирует ответ по материалам ветки и правилам общения. Точный текст появляется в тестовом чате.</div>':''}${n.tasks?.length?`<ul>${n.tasks.map(t=>`<li>${E(t)}</li>`).join('')}</ul>`:''}${n.sources?.length?`<div class="cascade-note">Источники: ${n.sources.map(id=>E(S.config.sources[id]?.title||id)).join(', ')}</div>`:''}</article>${edges.length?`<div class="cascade-children">${edges.map(e=>`<section class="cascade-path"><div class="cascade-edge">${E(e.label)}${e.conditions?.length?` · если ${E(conditionText(e.conditions))}`:''}</div>${e.target?walk(e.target):e.url?`<a class="cascade-reference" href="${E(e.url)}" target="_blank" rel="noopener noreferrer">Открыть ссылку ↗ ${E(e.url)}</a>`:'<small>Следующий переход не задан</small>'}</section>`).join('')}</div>`:''}</div>`;
 }
 let html=walk(branch.entry);
 const unattached=nodes.filter(n=>!seen.has(n.id));
 if(unattached.length)html+=`<div class="cascade-unlinked"><h3>Другие шаги ветки</h3><p class="help-label">Вход через действие сервиса, свободный запрос или ещё не настроенный переход.</p>${unattached.map(n=>seen.has(n.id)?'':walk(n.id)).join('')}</div>`;
 if(contentOnly)return html;
 return cascadeFrame(html,branch.title);
}
function cascadeFrame(html,title){return `<div class="cascade-controls"><span>«${E(title)}» · шаги сверху вниз</span><div>${button('−','zoom-out','aria-label="Отдалить"')}<output id="zoom-level">100%</output>${button('+','zoom-in','aria-label="Приблизить"')}${button('100%','zoom-reset')}${button('Показать всю ветку','zoom-fit')}</div></div><div class="cascade-viewport" tabindex="0" aria-label="Каскад сверху вниз. Прокрутка по горизонтали и вертикали; Ctrl и колесо — масштаб."><div class="cascade-tree">${html}</div></div>`;
}
function renderCanvas(){
 if(S.branch==='all'){
 const start=S.config.branches.find(b=>b.id===S.config.nodes.find(n=>n.id===S.config.start)?.branch)||S.config.branches[0];
 const content=b=>renderCascade(S.config.nodes.filter(n=>n.branch===b.id),b,true);
 $('#canvas-content').innerHTML=cascadeFrame(`<div class="overview-root"><h2>Знакомство</h2>${content(start)}</div><div class="overview-branches">${S.config.branches.filter(b=>b.id!==start.id).map(b=>`<section class="overview-branch"><button class="overview-branch-title" data-action="choose-branch" data-id="${E(b.id)}">${E(b.title)} · открыть ветку ↗</button>${content(b)}</section>`).join('')}</div>`,'Весь сценарий');applyZoom(S.fit);return;
 }
 const nodes=S.config.nodes.filter(n=>n.branch===S.branch), branch=S.config.branches.find(b=>b.id===S.branch);
 if(S.view==='cascade'){$('#canvas-content').innerHTML=renderCascade(nodes,branch);applyZoom(S.fit);return}
 if(S.view==='list'){$('#canvas-content').innerHTML=`<div class="node-list">${nodes.map((n,i)=>`<button data-action="select-node" data-id="${n.id}" class="list-node ${n.id===S.selected?'selected':''}"><div class="list-node-head"><span class="list-number">${String(i+1).padStart(2,'0')}</span><div><h3>${E(n.title)}</h3><small>${kinds[n.kind]}${n.id===branch.entry?' · вход в ветку':''}</small></div></div><p>${E(n.text||actions[n.action]||'Ответ по материалам')}</p><div class="list-links">${outgoing(n).map(x=>`<span>${E(x.label)} → ${E(S.config.nodes.find(z=>z.id===x.target)?.title||x.target)}</span>`).join('')}</div></button>`).join('')}</div>`;return}
 const ids=new Set(nodes.map(n=>n.id)), levels={},queue=[branch.entry];levels[branch.entry]=0;
 while(queue.length){let id=queue.shift(),n=nodes.find(n=>n.id===id);if(!n)continue;for(const e of outgoing(n)){if(ids.has(e.target)&&levels[e.target]===undefined){levels[e.target]=levels[id]+1;queue.push(e.target)}}}
 let extra=Math.max(0,...Object.values(levels))+1;for(const n of nodes)if(levels[n.id]===undefined)levels[n.id]=extra++;
 const counts={},pos={};for(const n of nodes){let d=levels[n.id],col=counts[d]||0;counts[d]=col+1;pos[n.id]={x:36+col*265,y:28+d*180}}
 const width=Math.max(480,...Object.values(pos).map(p=>p.x+270)),height=Math.max(430,...Object.values(pos).map(p=>p.y+170));
 const lines=nodes.flatMap(n=>outgoing(n).filter(e=>pos[e.target]).map((edge,i)=>{let a=pos[n.id],b=pos[edge.target],x=a.x+113,y=a.y+130,tx=b.x+113,ty=b.y;const back=ty<y;return `<path class="edge" marker-end="url(#arrow)" d="M ${x} ${y} C ${back?x+140:x} ${y+35},${back?tx+140:tx} ${ty-35},${tx} ${ty}"/><text class="edge-label" x="${x+8}" y="${y+22+i*11}">${E(edge.label.slice(0,32))}</text>`})).join('');
 $('#canvas-content').innerHTML=`<div class="graph" style="width:${width}px;height:${height}px"><svg width="${width}" height="${height}"><defs><marker id="arrow" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="#91a58d"/></marker></defs>${lines}</svg>${nodes.map(n=>`<button class="graph-node ${n.id===S.selected?'selected':''}" style="left:${pos[n.id].x}px;top:${pos[n.id].y}px" data-action="select-node" data-id="${n.id}"><div class="node-type"><i class="${n.kind==='answer'?'llm':''}"></i>${kinds[n.kind]}${n.id===branch.entry?' · вход':''}</div><h3>${E(n.title)}</h3><div class="node-snippet">${E(n.text||actions[n.action]||'Ответ по материалам')}</div><div class="node-footer"><span>${(n.buttons||[]).length} кнопок</span><span>${n.routes?.length?'есть условия':'открыть →'}</span></div></button>`).join('')}</div>`;
}
function conditionRows(list,scope){return list.map((r,i)=>`<div class="condition-edit"><select aria-label="Поле условия" data-condition="${scope}" data-index="${i}" data-prop="field">${options(fieldNames(),r.field)}</select><select aria-label="Сравнение" data-condition="${scope}" data-index="${i}" data-prop="op">${options(ops,r.op)}</select><input aria-label="Значение" value="${E(r.value)}" data-condition="${scope}" data-index="${i}" data-prop="value"><button type="button" class="icon-button" data-action="remove-condition" data-scope="${scope}" data-index="${i}" aria-label="Удалить условие">×</button></div>${scope==='routes'?`<label class="field"><span>Тогда перейти</span><select data-condition="routes" data-index="${i}" data-prop="target">${targets(r.target,false)}</select></label>`:''}`).join('')}
function renderInspector(){const n=currentNode();if(!n){$('#inspector').innerHTML='<div class="empty">Добавьте первый шаг в эту ветку</div>';return}
 $('#inspector').innerHTML=`${S.view==='cascade'?'<button class="text-button close-cascade" data-action="close-inspector">Закрыть редактор ×</button>':''}<div class="inspector-header"><div><span class="eyebrow">РЕДАКТИРОВАНИЕ ШАГА</span><h2 style="margin-top:8px">${E(n.title)}</h2><small>Изменения сначала сохраняются в черновик</small></div><span class="chip">${kinds[n.kind]}</span></div><div class="inspector-body">${field('Название шага',input(n.title,'data-node="title"'))}${field('Тип шага',`<select data-node="kind">${options(kinds,n.kind)}</select>`)}${n.kind==='action'?field('Что делает бот',`<select data-node="action">${options(actions,n.action)}</select>`):''}${field('Сообщение для ребёнка / общий текст',area(n.text,'data-node="text" rows="5"'),n.kind==='answer'?'Это задание LLM. Ответ будет сформирован по материалам ветки.':'Такое сообщение увидит пользователь. Можно использовать {city}, {age} и другие ответы.')}${field('Вариант для взрослого',area(n.adult_text,'data-node="adult_text" rows="3"'),'Если пусто, используется общий текст.')}${n.kind==='question'?`<div class="field-row">${field('Какой ответ запоминаем',`<select data-node="field">${options(fieldNames(),n.field)}</select>`)}${field('Формат ответа',`<select data-node="input_type">${options({text:'Текст',number:'Число',city:'Город',boolean:'Да / нет'},n.input_type)}</select>`)}</div>${check('Ответ обязателен',n.required,'data-node="required"')}`:''}${field(n.kind==='question'?'После ответа перейти':'Следующий шаг',`<select data-node="next">${targets(n.next)}</select>`)}<div class="section-label">Кнопки <span>${n.buttons.length}</span></div><div>${n.buttons.map((b,i)=>`<div class="button-edit"><div class="row-tools"><button type="button" class="icon-button" data-action="button-up" data-index="${i}" aria-label="Кнопку выше">↑</button><button type="button" class="icon-button" data-action="button-down" data-index="${i}" aria-label="Кнопку ниже">↓</button><button type="button" class="icon-button" data-action="delete-button" data-index="${i}" aria-label="Удалить кнопку">×</button></div>${field('Название кнопки',input(b.label,`data-button="label" data-index="${i}"`))}${field('Открывает шаг',`<select data-button="target" data-index="${i}">${targets(b.target)}</select>`)}${field('Или внешняя ссылка',input(b.url||'',`data-button="url" data-index="${i}" placeholder="https://…"`))}<details><summary class="help-label">Условия показа и значения</summary>${conditionRows(b.conditions||[],`button-${i}`)}<button type="button" class="text-button" data-action="add-condition" data-scope="button-${i}">+ Условие кнопки</button>${field('Установить роль',`<select data-button-role="${i}">${options(roles,b.values?.role||'',true)}</select>`)}${field('Текст будущего напоминания',input(b.values?.reminder_text||'',`data-button-reminder="${i}"`))}</details></div>`).join('')}</div><button type="button" class="add-row" data-action="add-button">+ Добавить кнопку</button><div class="section-label">Чек-лист</div>${field('По одному пункту в строке',area(n.tasks.join('\n'),'data-node="tasks" rows="3"'))}<div class="section-label">Условия и переходы</div><div class="help-label">Например: возраст меньше 18. Условия показа должны выполняться вместе; переходы проверяются сверху вниз.</div>${conditionRows(n.conditions||[],'conditions')}<button type="button" class="text-button" data-action="add-condition" data-scope="conditions">+ Условие показа шага</button>${conditionRows(n.routes||[],'routes')}<button type="button" class="text-button" data-action="add-condition" data-scope="routes">+ Условный переход</button><div class="section-label">Источники ответа</div>${Object.entries(S.config.sources).map(([id,x])=>check(x.title,n.sources.includes(id),`data-source-check="${E(id)}"`)).join('')}</div><div class="inspector-footer"><button class="text-button" data-action="duplicate-node">Дублировать</button><button class="text-button" data-action="delete-node" style="color:#ad644d">Удалить шаг</button></div>`;
}
function modal(content,acceptLabel,handler){$('#modal-content').innerHTML=content+`<div class="modal-actions"><button value="cancel" class="button secondary">Отмена</button><button type="button" id="modal-accept" class="button primary">${acceptLabel}</button></div>`;$('#modal').showModal();$('#modal-accept').onclick=()=>safe(async()=>{await handler();$('#modal').close()})}
function newId(prefix){return prefix+'_'+Math.random().toString(36).slice(2,9)}
function branchDialog(isNew=false){const b=isNew?{id:newId('branch'),title:'Новая ветка',entry:'',status:'draft',roles:Object.keys(roles),prompt:'',keywords:[]}:S.config.branches.find(b=>b.id===S.branch);modal(`<h2>${isNew?'Новая ветка':'Настройки ветки'}</h2>${field('Название',input(b.title,'id="branch-title"'))}${field('Готовность',`<select id="branch-status">${options({ready:'Готово',draft:'Не готово'},b.status)}</select>`)}${!isNew?field('Первый шаг',`<select id="branch-entry">${targets(b.entry,false)}</select>`):''}<div class="field-label">Для кого</div>${Object.entries(roles).map(([id,label])=>check(label,b.roles.includes(id),`data-role-choice="${id}"`)).join('')}${field('Как распознать ветку: ключевые слова через запятую',input(b.keywords.join(', '),'id="branch-keywords"'))}${field('Правила LLM для этой ветки',area(b.prompt,'id="branch-prompt" rows="4"'))}${!isNew&&b.id!=='start'?button('Удалить ветку','delete-branch','','danger'):''}`,'Применить',()=>{b.title=$('#branch-title').value;b.status=$('#branch-status').value;b.roles=[...document.querySelectorAll('[data-role-choice]:checked')].map(e=>e.dataset.roleChoice);b.keywords=$('#branch-keywords').value.split(',').map(x=>x.trim()).filter(Boolean);b.prompt=$('#branch-prompt').value;if(isNew){const id=newId('step');b.entry=id;S.config.branches.push(b);S.config.nodes.push({id,branch:b.id,title:'Первый шаг',kind:'message',text:'Чем помочь?',adult_text:'',buttons:[{label:'Главное меню',target:S.config.menu}],next:'',conditions:[],routes:[],tasks:[],sources:[]});S.branch=b.id;S.selected=id;const menu=S.config.nodes.find(n=>n.id===S.config.menu);menu.buttons.push({label:b.title,target:id})}else b.entry=$('#branch-entry').value;changed();renderScenarios()})}
function deleteNodes(ids,branchId=null){const references=S.config.nodes.flatMap(n=>outgoing(n).filter(e=>ids.includes(e.target)).map(e=>n.title+' → '+e.label));const remain=S.config.nodes.filter(n=>!ids.includes(n.id));if(!remain.length)throw Error('В сценарии должен остаться хотя бы один шаг.');modal(`<h2>${branchId?'Удалить ветку и её шаги?':'Удалить шаг?'}</h2><p class="help-label">Все ведущие сюда переходы будут направлены в выбранный шаг. Изменение попадёт в MAX только после публикации.</p><div class="callout">${references.length?references.map(E).join('<br>'):'Входящих кнопок нет'}</div>${field('Куда перенаправить',`<select id="replace-target">${options(Object.fromEntries(remain.map(n=>[n.id,n.title])),S.config.menu)}</select>`)}`,'Удалить и перенаправить',()=>{const replacement=$('#replace-target').value;for(const n of S.config.nodes){if(ids.includes(n.next))n.next=replacement;for(const b of n.buttons)if(ids.includes(b.target))b.target=replacement;for(const r of n.routes||[])if(ids.includes(r.target))r.target=replacement}for(const b of S.config.branches)if(ids.includes(b.entry))b.entry=replacement;for(const v of Object.values(S.config.ui))if(ids.includes(v.target))v.target=replacement;for(const key of Object.keys(S.config.bindings||{}))if(ids.includes(S.config.bindings[key]))S.config.bindings[key]=replacement;for(const key of ['start','menu'])if(ids.includes(S.config[key]))S.config[key]=replacement;S.config.nodes=remain;if(branchId){S.config.branches=S.config.branches.filter(b=>b.id!==branchId);S.branch=remain.find(n=>n.id===replacement).branch}S.selected=replacement;changed();renderScenarios()})}
function renderMaterials(){const c=S.config;$('#main').innerHTML=`<div class="page">${pageHead('Материалы, на которые можно опереться','Пополняем базу через Codex. Здесь можно увидеть, проверить и отредактировать её содержимое.',button('+ Материал','new-material','','lime'))}${S.warnings.length?`<div class="warning-list">${S.warnings.map(w=>E(w.text)).join('<br>')}</div>`:''}<div class="card"><h2>База ответов <span class="chip">${c.materials.length} материалов</span></h2><table class="table"><thead><tr><th>Материал</th><th>Тема и аудитория</th><th>Проверен</th><th></th></tr></thead><tbody>${c.materials.map(m=>`<tr><td class="title-cell">${E(m.title)}<small>${m.enabled?'Используется в ответах':'Отключён'}</small></td><td>${m.branches.map(id=>E(c.branches.find(b=>b.id===id)?.title||id)).join(', ')}<small>${E(rolesView(m.roles))}${m.regions?.length?' · '+E(m.regions.join(', ')):''}</small></td><td>${E(m.checked||'Не проверен')}<small>Проверка раз в ${m.review_days||90} дней</small></td><td>${button('Открыть','edit-material',`data-id="${m.id}"`)}</td></tr>`).join('')}</tbody></table></div><div class="card"><div class="page-title"><h2>Источники и ссылки</h2>${button('+ Источник','new-source')}</div><table class="table"><thead><tr><th>Источник</th><th>Область применения</th><th></th></tr></thead><tbody>${Object.entries(c.sources).map(([id,s])=>`<tr><td>${E(s.title)}<br><a class="source-link" href="${E(s.url)}" target="_blank" rel="noopener noreferrer">${E(s.url)}</a></td><td>${E(s.scope)}<small>Проверен: ${E(s.checked)}</small></td><td>${button('Изменить','edit-source',`data-id="${E(id)}"`)}</td></tr>`).join('')}</tbody></table></div></div>`}
function materialDialog(id){const m=S.config.materials.find(x=>x.id===id)||{id:newId('material'),title:'Новый материал',text:'',branches:[S.branch],regions:[],roles:[],sources:[],checked:'',review_days:90,enabled:false,min_age:null,max_age:null};modal(`<h2>Материал базы знаний</h2>${field('Название',input(m.title,'id="m-title"'))}${field('Содержание',area(m.text,'id="m-text" rows="8"'))}${field('Темы',`<select id="m-branches" multiple size="4">${S.config.branches.map(b=>`<option value="${b.id}" ${m.branches.includes(b.id)?'selected':''}>${E(b.title)}</option>`).join('')}</select>`)}${field('Регионы или города через запятую; пусто — вся Россия',input(m.regions.join(', '),'id="m-regions"'))}<div class="field-row">${field('Возраст от',input(m.min_age??'','id="m-min" type="number" min="0" max="100"'))}${field('Возраст до',input(m.max_age??'','id="m-max" type="number" min="0" max="100"'))}</div><div class="field-label">Роли (ничего не выбрано — все)</div>${Object.entries(roles).map(([k,v])=>check(v,m.roles.includes(k),`data-m-role="${k}"`)).join('')}${field('Источники',`<select id="m-sources" multiple size="4">${Object.entries(S.config.sources).map(([k,v])=>`<option value="${k}" ${m.sources.includes(k)?'selected':''}>${E(v.title)}</option>`).join('')}</select>`)}<div class="field-row">${field('Дата проверки',input(m.checked,'id="m-checked" type="date"'))}${field('Перепроверять через дней',input(m.review_days,'id="m-days" type="number" min="1"'))}</div>${check('Использовать материал в ответах',m.enabled,'id="m-enabled"')}`,'Сохранить материал',()=>{Object.assign(m,{title:$('#m-title').value,text:$('#m-text').value,branches:[...$('#m-branches').selectedOptions].map(o=>o.value),regions:$('#m-regions').value.split(',').map(x=>x.trim()).filter(Boolean),roles:[...document.querySelectorAll('[data-m-role]:checked')].map(e=>e.dataset.mRole),sources:[...$('#m-sources').selectedOptions].map(o=>o.value),checked:$('#m-checked').value,review_days:Number($('#m-days').value)||90,min_age:$('#m-min').value===''?null:Number($('#m-min').value),max_age:$('#m-max').value===''?null:Number($('#m-max').value),enabled:$('#m-enabled').checked});if(!S.config.materials.includes(m))S.config.materials.push(m);changed();renderMaterials()})}
function sourceDialog(id){const k=id||newId('source'),s=S.config.sources[k]||{title:'Новый источник',url:'https://',scope:'',checked:''};modal(`<h2>Источник</h2>${field('Название кнопки',input(s.title,'id="s-title"'))}${field('HTTPS-ссылка',input(s.url,'id="s-url" type="url"'))}${field('Для чего используется и ограничения',area(s.scope,'id="s-scope"'))}${field('Дата проверки',input(s.checked,'id="s-checked" type="date"'))}<p class="help-label">Сохранение не означает, что ссылка проверена. Дату проверки отмечаем после просмотра содержания.</p>`,'Сохранить',()=>{S.config.sources[k]={...s,title:$('#s-title').value,url:$('#s-url').value,scope:$('#s-scope').value,checked:$('#s-checked').value};changed();renderMaterials()})}
function renderRules(){const r=S.config.rules;$('#main').innerHTML=`<div class="page">${pageHead('Где думает модель','Разделяем слова, решения по сценарию и реальные действия.') }<div class="three-col"><div class="card"><span class="chip orange">01 · LLM</span><h2 style="margin-top:15px">Понимает запрос</h2><p>Из свободного сообщения выбирает ветку и извлекает параметры: город, возраст, профессию. Простой числовой ответ и кнопки обрабатываются без модели.</p></div><div class="card"><span class="chip orange">02 · LLM</span><h2 style="margin-top:15px">Объясняет по базе</h2><p>Отвечает на уточняющий вопрос по материалам выбранной ветки. Правила общения и ваши примеры влияют на этот ответ. Ссылки берутся из базы.</p></div><div class="card"><span class="chip">03 · КОД</span><h2 style="margin-top:15px">Выполняет действие</h2><p>Ищет реальные вакансии, применяет фильтры, ведёт чек-лист и сохраняет напоминания. Модель сама этого не делает.</p></div></div><div class="callout">Модель: <strong>${E(S.model)}</strong>. В эвалах LLM дополнительно выступает оценщиком. Это рекомендация для вас, а не окончательный вердикт. Хорошие и плохие примеры помогают настроить поведение через инструкции; веса модели здесь не дообучаются.</div><div class="card"><h2>Общие правила</h2><div class="rule-grid">${Object.entries({tone:'Тон общения',length:'Длина и структура ответа',forbidden:'Границы и запрещённые темы',clarify:'Когда уточнять',router:'Правила понимания запроса',judge:'Критерии LLM-оценщика'}).map(([k,v])=>field(v,area(r[k],`data-rule="${k}" rows="4"`))).join('')}</div></div><div class="card"><h2>Примеры для модели</h2><p>Примеры добавляются из результатов эвалов. Они попадут в реальные ответы после публикации.</p>${S.config.examples.length?S.config.examples.map((x,i)=>`<div class="eval-result"><span class="chip ${x.rating==='bad'?'orange':''}">${x.rating==='bad'?'Так отвечать не надо':'Хороший ответ'}</span><p>${E(x.question)}</p><div class="eval-transcript">${E(x.answer)}</div><button class="text-button" data-action="remove-example" data-index="${i}">Удалить пример</button></div>`).join(''):'<small>Пока нет примеров. Откройте «Эвалы» и оцените ответ.</small>'}</div></div>`}
function renderTemplates(){const q=($('#template-filter')?.value||'').toLowerCase();$('#main').innerHTML=`<div class="page">${pageHead('Каждое служебное сообщение','Ошибки, карточки вакансий, напоминания и подписи динамических кнопок.')}<div class="callout">Значения в фигурных скобках подставляет бот: {title}, {city}, {date}. Их можно переставлять. Ссылку-переход у динамической кнопки меняйте, если хотите вместо стандартного действия открыть другой шаг.</div><div class="search-line"><input id="template-filter" placeholder="Найти текст или кнопку…" value="${E(q)}"><span class="muted">${Object.keys(S.config.ui).length} элементов</span></div><div class="ui-templates">${Object.entries(S.config.ui).filter(([k,v])=>!q||(k+' '+v.text).toLowerCase().includes(q)).map(([k,v])=>`<div class="template-card"><small>${v.category==='button'?'КНОПКА':'СООБЩЕНИЕ'} · ${E(k)}</small>${area(v.text,`data-template="${k}" data-prop="text"`)}${v.category==='button'?`${check('Скрыть кнопку',v.hidden,`data-template="${k}" data-prop="hidden"`)}${field('Вместо действия перейти',`<select data-template="${k}" data-prop="target">${targets(v.target)}</select>`)}`:''}</div>`).join('')}</div></div>`}
function renderEvals(){ $('#main').innerHTML=`<div class="page">${pageHead('Проверяем качество, а не впечатление','Одинаковые вопросы, понятные критерии и ваши примеры хороших ответов.',button('+ Тестовый случай','new-eval','','lime'))}<div class="callout">Проверка использует настоящий LLM API и расходует его баланс. Тестовые диалоги сохраняются здесь; реальные переписки MAX не сохраняются. Черновик фиксируется на момент запуска.</div><div class="card"><div class="page-title"><h2>Набор проверок <span class="chip">${S.config.evaluations.length}</span></h2>${button('Запустить все проверки','run-evals','','primary')}</div><table class="table"><thead><tr><th>Сценарий</th><th>Критерии</th><th></th></tr></thead><tbody>${S.config.evaluations.map(c=>`<tr><td class="title-cell">${E(c.title)}<small>${c.messages.length} сообщений</small></td><td>${E(c.criteria)}</td><td><div class="top-actions">${button('Изменить','edit-eval',`data-id="${c.id}"`)}${button('Проверить','run-eval',`data-id="${c.id}"`)}</div></td></tr>`).join('')}</tbody></table></div><div class="card"><div class="page-title"><h2>Результаты</h2>${button('История проверок','eval-history')}</div><div id="eval-status" class="help-label"></div><div id="eval-results"></div></div></div>`;renderEvalResults() }
function evalDialog(id){const c=S.config.evaluations.find(x=>x.id===id)||{id:newId('case'),title:'Новый тест',messages:[],criteria:'',good:'',bad:''};modal(`<h2>Тестовый случай</h2>${field('Название',input(c.title,'id="e-title"'))}${field('Сообщения пользователя — каждое с новой строки',area(c.messages.join('\n'),'id="e-messages" rows="5"'))}${field('Как понять, что бот справился',area(c.criteria,'id="e-criteria"'))}${field('Пример хорошего ответа',area(c.good,'id="e-good"'))}${field('Пример плохого ответа',area(c.bad,'id="e-bad"'))}`,'Сохранить тест',()=>{Object.assign(c,{title:$('#e-title').value,messages:$('#e-messages').value.split('\n').map(x=>x.trim()).filter(Boolean),criteria:$('#e-criteria').value,good:$('#e-good').value,bad:$('#e-bad').value});if(!c.messages.length)throw Error('Добавьте хотя бы одно сообщение.');if(!S.config.evaluations.includes(c))S.config.evaluations.push(c);changed();renderEvals()})}
function renderEvalResults(){const el=$('#eval-results');if(!el)return;el.innerHTML=S.evalResults.length?S.evalResults.map((r,i)=>`<div class="eval-result ${r.judge?.passed?'':'fail'}"><div class="page-title"><h3>${E(r.title)}</h3><span class="chip ${r.judge?.passed?'':'orange'}">${r.judge?.error?'Без оценки':`${r.judge?.score??'—'} / 5 · ${r.judge?.passed?'пройден':'нужна правка'}`}</span></div><p>${E(r.judge?.reason||r.judge?.error||'')}</p><details><summary>Посмотреть диалог и ход работы</summary>${r.transcript.map(t=>`<p><strong>Пользователь:</strong> ${E(t.user)}</p><div class="eval-transcript">${E(t.bot)}</div>`).join('')}<div class="help-label">${(r.trace||[]).map(t=>E(t.purpose||t.title||t.kind)).join(' → ')}</div></details><div class="top-actions" style="margin-top:15px">${button('✓ Хороший пример','example-good',`data-index="${i}"`)}${button('× Плохой пример','example-bad',`data-index="${i}"`)}</div></div>`).join(''):'<small>Запустите тест, чтобы увидеть ответ бота и оценку LLM.</small>'}
async function runEvals(ids=[]){await save();const result=await api('evaluations/run',{case_ids:ids});$('#eval-status').textContent='Проверка идёт. Можно продолжить работу — запуск использует текущую сохранённую версию.';let key=result.job;const poll=async()=>{const job=await api('evaluations/jobs/'+key);S.evalResults=job.results;if($('#eval-status'))$('#eval-status').textContent=`${job.status==='done'?'Готово':job.status==='error'?'Ошибка: '+job.error:'Выполняется'} · ${job.results.length} / ${job.total}`;renderEvalResults();if(['queued','running'].includes(job.status))setTimeout(()=>safe(poll),2500)};setTimeout(()=>safe(poll),1000)}
function renderSearch(){const st=S.config.search;$('#main').innerHTML=`<div class="page">${pageHead('Почему нашлась именно эта работа','Прямой запрос к «Работе России» и причины исключения вакансий. Без LLM на этом экране.')}<div class="two-col"><div class="card"><h2>Условия тестового поиска</h2><form id="search-form">${field('Профессия',input('грузчик','name="query" placeholder="Любая профессия"'))}<div class="field-row">${field('Город',input('Тула','name="city" required'))}${st.contract_version>=2?'<small>Регион определяется по проверенному справочнику. Для одноимённых городов укажите город и регион через запятую.</small>':`${field('Код региона',`<select name="region_code">${options({'7100000000000':'Тульская область','7700000000000':'Москва','5000000000000':'Московская область','7800000000000':'Санкт-Петербург','1600000000000':'Татарстан','6600000000000':'Свердловская область','5400000000000':'Новосибирская область'},'7100000000000')}</select>`)}`}</div><div class="field-row">${field('Возраст',input(19,'name="age" type="number" min="0" max="100"'))}${field('Опыт, лет',input(0,'name="experience" type="number" min="0"'))}</div>${field('Зарплата от, ₽ в месяц',input('','name="salary" type="number" min="0" placeholder="Неважно"'))}${check('С предоставлением жилья',false,'name="housing"')}<button class="button primary" type="submit">Проверить поиск ↗</button></form></div><div class="card"><h2>Правила выдачи бота</h2>${field('Вакансий в одном показе',input(st.page_size,'data-search-setting="page_size" type="number" min="1" max="10"'))}${field('Страниц API за один запрос',input(st.scan_pages,'data-search-setting="scan_pages" type="number" min="1" max="5"'))}${st.contract_version>=2?'<p>Названные человеком условия проверяются всегда. Неполные карточки показываются отдельно с указанием неподтверждённых условий.</p>':`${check('Проверять город по адресу',st.filter_city,'data-search-setting="filter_city"')}${check('Применять пожелание по зарплате',st.filter_salary,'data-search-setting="filter_salary"')}${check('Оставлять вакансии без зарплаты',st.include_unknown_salary,'data-search-setting="include_unknown_salary"')}`}${field('Минимальный возраст для поиска',input(st.min_age,'data-search-setting="min_age" type="number" min="0" max="100"'))}${field('После скольких «не подошло» показать HH',input(st.hh_after,'data-search-setting="hh_after" type="number" min="1"'))}<small>График сопоставляется с данными карточки. Бесплатность и конкретные условия жилья нужно уточнить у работодателя.</small></div></div><div id="search-results"></div></div>`}
async function renderHistory(){ $('#main').innerHTML=`<div class="page">${pageHead('Можно вернуться назад','Опубликованные версии неизменяемы. Восстановление создаёт черновик для проверки.',button('Экспорт черновика','export'))}<div class="card" id="history-list">Загрузка…</div></div>`;const rows=await api('history');if(S.section!=='history')return;$('#history-list').innerHTML=`<table class="table"><thead><tr><th>Версия</th><th>Дата</th><th>Комментарий</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>№ ${r.id} ${r.id===S.published?'<span class="chip">В MAX</span>':''}</td><td>${E(new Date(r.created_at).toLocaleString('ru'))}</td><td>${E(r.note)}</td><td>${button('Восстановить в черновик','restore',`data-id="${r.id}"`)}</td></tr>`).join('')}</tbody></table>`}
async function renderEvents(){ $('#main').innerHTML=`<div class="page">${pageHead('Что происходит в боте','Только счётчики событий по дням. Без пользователей, сообщений и истории переписки.')}<div class="card" id="events-list">Загрузка…</div></div>`;const rows=await api('events');if(S.section!=='events')return;const names={llm_router:'LLM разобрала запрос',llm_answer:'LLM ответила по базе',search:'Выполнен поиск',search_error:'Ошибка портала вакансий'};$('#events-list').innerHTML=rows.length?`<table class="table"><thead><tr><th>День</th><th>Событие</th><th>Ветка</th><th>Количество</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${E(r.day)}</td><td>${E(names[r.kind]||r.kind)}</td><td>${E(S.config.branches.find(b=>b.id===r.branch)?.title||r.branch)}</td><td>${r.count}</td></tr>`).join('')}</tbody></table>`:'<div class="empty">Счётчики появятся после новых обращений в MAX.</div>'}
function traceHtml(trace){return trace.map(t=>`<div class="trace-item"><span class="trace-label">${E({llm_router:'LLM · понимание запроса',llm_answer:'LLM · ответ по материалам',step:'Шаг сценария',search:'Работа России',materials:'База знаний',llm_error:'Ошибка LLM'}[t.kind]||t.kind)}</span><div>${E(t.purpose||t.title||t.code||'')}</div>${t.fields?`<pre>${E(JSON.stringify(t.fields,null,2))}</pre>`:''}${t.parameters?`<pre>${E(JSON.stringify(t.parameters,null,2))}</pre><div>Из API: ${t.fetched}; показано: ${t.shown}</div>`:''}${t.excluded?.length?`<details><summary>Не показаны: ${t.excluded.length}</summary>${t.excluded.map(x=>`<p>${E(x.title)} — ${E(x.reason)}</p>`).join('')}</details>`:''}${t.sources?`<small>Источники: ${E(t.sources.join(', '))}</small>`:''}${t.seconds?`<small>${t.seconds} сек.</small>`:''}</div>`).join('')}
function appendBubble(text,type,reply=null){const el=document.createElement('div');el.className='bubble '+type;if(reply?.format==='markdown'){const links=/\[([^\]]+)\]\((https:\/\/[^\s)]+)\)/g;let start=0,match;while((match=links.exec(text))){el.append(document.createTextNode(text.slice(start,match.index)));const a=document.createElement('a');a.href=match[2];a.target='_blank';a.rel='noopener noreferrer';a.textContent=match[1];el.append(a);start=links.lastIndex}el.append(document.createTextNode(text.slice(start)))}else el.textContent=text;if(reply?.attachments){const holder=document.createElement('div');holder.className='chat-buttons';for(const a of reply.attachments)for(const row of a.payload?.buttons||[])for(const b of row){const item=document.createElement(b.type==='link'?'a':'button');item.textContent=b.text;if(b.type==='link'){item.href=b.url;item.target='_blank';item.rel='noopener noreferrer'}else{item.type='button';item.dataset.action='chat-button';item.dataset.payload=b.payload}holder.append(item)}el.append(holder)}$('#chat-log').append(el);$('#chat-log').scrollTop=$('#chat-log').scrollHeight}
async function chat(text='',payload=null,reset=false){if(S.busy)return;S.busy=true;$('#chat-input').disabled=true;$('#chat-error').hidden=true;try{await save();if(reset){$('#chat-log').innerHTML='';S.chat=''}if(text)appendBubble(text,'user');const typing=document.createElement('div');typing.className='bubble bot';typing.textContent='Разбираюсь…';$('#chat-log').append(typing);try{const r=await api('preview',{session:S.chat,text,payload,reset});S.chat=r.session;typing.remove();for(const msg of r.replies)appendBubble(msg.text,'bot',msg);$('#trace').innerHTML=traceHtml(r.trace);$('#preview-node').textContent=S.config.nodes.find(n=>n.id===r.node)?.title||''}catch(e){typing.remove();throw e}}catch(e){$('#chat-error').textContent=e.message;$('#chat-error').hidden=false}finally{S.busy=false;$('#chat-input').disabled=false;$('#chat-input').focus()}}
function resizePreview(full){
 const log=$('#chat-log'),atEnd=log.scrollHeight-log.scrollTop-log.clientHeight<40;
 document.body.classList.toggle('preview-full',full);
 $('#preview-size').textContent=full?'Боковая панель':'На весь экран';
 $('#preview-size').setAttribute('aria-pressed',String(full));
 $('.sidebar').inert=full;$('.app-shell').inert=full;
 if(atEnd)log.scrollTop=log.scrollHeight;
}
function togglePreview(open){
 $('#preview').hidden=!open;document.body.classList.toggle('preview-open',open);resizePreview(open);
 if(open){if(!$('#chat-log').children.length)safe(()=>chat('',null,true));else $('#chat-input').focus()}
 else $('#preview-toggle').focus();
}
let chatFontSize=18;
function changeChatFont(delta){
 const log=$('#chat-log'),atEnd=log.scrollHeight-log.scrollTop-log.clientHeight<40;
 chatFontSize=Math.max(16,Math.min(24,chatFontSize+delta));
 $('#preview').style.setProperty('--chat-font-size',chatFontSize+'px');
 $('#chat-font-size').textContent=chatFontSize+' px';
 $('[data-action="chat-font-down"]').disabled=chatFontSize===16;
 $('[data-action="chat-font-up"]').disabled=chatFontSize===24;
 if(atEnd)log.scrollTop=log.scrollHeight;
}
document.addEventListener('keydown',ev=>{if(ev.key==='Escape'&&!$('#preview').hidden&&!$('#modal').open){ev.preventDefault();togglePreview(false)}});
function conditionList(scope){const n=currentNode();if(scope.startsWith('button-')){const b=n.buttons[Number(scope.split('-')[1])];return b.conditions??(b.conditions=[])}return n[scope]??(n[scope]=[])}
document.addEventListener('change',ev=>{const t=ev.target;if(!S.config)return;const value=t.type==='checkbox'?t.checked:t.value;if(t.id==='branch-select'){navigateBranch(value);return}if(t.dataset.node){const n=currentNode(),key=t.dataset.node;n[key]=key==='tasks'?value.split('\n').filter(Boolean):value;if(key==='kind'){if(value==='question'){n.field||='answer_'+n.id;n.input_type||='text';n.required??=false;n.next||=S.config.menu}if(value==='action')n.action||='reminders';renderInspector()}changed();renderCanvas()}if(t.dataset.button){const b=currentNode().buttons[Number(t.dataset.index)];b[t.dataset.button]=value;if(t.dataset.button==='url'&&value)b.target='';if(t.dataset.button==='target'&&value)b.url='';changed();renderCanvas()}if(t.dataset.buttonRole!==undefined){const b=currentNode().buttons[Number(t.dataset.buttonRole)];b.values??={};if(value)b.values.role=value;else delete b.values.role;changed()}if(t.dataset.buttonReminder!==undefined){const b=currentNode().buttons[Number(t.dataset.buttonReminder)];b.values??={};if(value)b.values.reminder_text=value;else delete b.values.reminder_text;changed()}if(t.dataset.condition){conditionList(t.dataset.condition)[Number(t.dataset.index)][t.dataset.prop]=value;changed();renderCanvas()}if(t.dataset.sourceCheck){const n=currentNode();n.sources=t.checked?[...new Set([...n.sources,t.dataset.sourceCheck])]:n.sources.filter(k=>k!==t.dataset.sourceCheck);changed()}if(t.dataset.rule){S.config.rules[t.dataset.rule]=value;changed()}if(t.dataset.template){S.config.ui[t.dataset.template][t.dataset.prop]=value;changed()}if(t.dataset.searchSetting){S.config.search[t.dataset.searchSetting]=t.type==='number'?Number(value):value;changed()}});
document.addEventListener('input',ev=>{if(ev.target.id==='template-filter'){const start=ev.target.selectionStart;renderTemplates();$('#template-filter').focus();$('#template-filter').setSelectionRange(start,start)}});
document.addEventListener('click',ev=>{const el=ev.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id,i=Number(el.dataset.index);safe(async()=>{
 if(a==='nav'){S.section=id;$('#notice').hidden=true;render()}
 else if(a==='view'){S.view=id;if(S.branch==='all'&&id!=='cascade')S.branch=S.config.branches[0].id;renderScenarios()}
 else if(a==='choose-branch'){navigateBranch(id)}
 else if(a==='branch-back'){const old=S.back.pop();if(old){Object.assign(S,{branch:old.branch,selected:old.selected,zoom:old.zoom,fit:false,editing:false});renderScenarios();const v=$('.cascade-viewport');if(v){v.scrollLeft=old.left;v.scrollTop=old.top}}}
 else if(a==='zoom-fit'){S.fit=true;applyZoom(true)}
 else if(a==='zoom-in'||a==='zoom-out'||a==='zoom-reset'){changeZoom(a==='zoom-reset'?1:S.zoom*(a==='zoom-in'?1.25:.8))}
 else if(a==='focus-node'){focusNode(id)}
 else if(a==='cascade-jump'){const n=S.config.nodes.find(n=>n.id===id);if(n){navigateBranch(n.branch);focusNode(id)}}
 else if(a==='close-inspector'){S.editing=false;$('.workbench')?.classList.remove('editing')}
 else if(a==='select-node'){S.selected=id;if(S.branch==='all'){navigateBranch(currentNode().branch);S.selected=id;}S.editing=true;$('.workbench')?.classList.add('editing');renderInspector();if(S.view!=='cascade')renderCanvas();else if(!$('#inspector .close-cascade'))$('#inspector').insertAdjacentHTML('afterbegin','<button class="text-button close-cascade" data-action="close-inspector">Закрыть редактор ×</button>')}
 else if(a==='new-branch')branchDialog(true);
 else if(a==='branch-settings')branchDialog();
 else if(a==='delete-branch'){$('#modal').close();deleteNodes(S.config.nodes.filter(n=>n.branch===S.branch).map(n=>n.id),S.branch)}
 else if(a==='new-node'||a==='duplicate-node'){const n=a==='duplicate-node'?structuredClone(currentNode()):{branch:S.branch,title:'Новый шаг',kind:'message',text:'',adult_text:'',buttons:[],next:'',conditions:[],routes:[],tasks:[],sources:[]};n.id=newId('step');if(a==='duplicate-node')n.title+=' · копия';S.config.nodes.push(n);S.selected=n.id;changed();renderScenarios()}
 else if(a==='delete-node')deleteNodes([S.selected]);
 else if(a==='add-button'){currentNode().buttons.push({label:'Новая кнопка',target:S.config.menu});changed();renderInspector();renderCanvas()}
 else if(a==='delete-button'){currentNode().buttons.splice(i,1);changed();renderInspector();renderCanvas()}
 else if(a==='button-up'||a==='button-down'){const list=currentNode().buttons,j=i+(a==='button-up'?-1:1);if(j>=0&&j<list.length){[list[i],list[j]]=[list[j],list[i]];changed();renderInspector();renderCanvas()}}
 else if(a==='add-condition'){const r={field:'age',op:'lt',value:'18'};if(el.dataset.scope==='routes')r.target=S.config.menu;conditionList(el.dataset.scope).push(r);changed();renderInspector();renderCanvas()}
 else if(a==='remove-condition'){conditionList(el.dataset.scope).splice(i,1);changed();renderInspector();renderCanvas()}
 else if(a==='new-material'||a==='edit-material')materialDialog(id);
 else if(a==='new-source'||a==='edit-source')sourceDialog(id);
 else if(a==='new-eval'||a==='edit-eval')evalDialog(id);
 else if(a==='run-evals'||a==='run-eval')await runEvals(id?[id]:[]);
 else if(a==='eval-history'){const runs=await api('evaluations/history');S.evalResults=runs.flatMap(r=>r.results.map(x=>({...x,title:`${x.title} · запуск ${r.id}, черновик ${r.revision}`})));renderEvalResults()}
 else if(a==='example-good'||a==='example-bad'){const r=S.evalResults[i],last=r.transcript.at(-1);modal(`<h2>${a==='example-good'?'Хороший':'Плохой'} пример для модели</h2>${field('Ветка',`<select id="example-branch">${options({all:'Все ветки',...Object.fromEntries(S.config.branches.map(b=>[b.id,b.title]))},r.trace.findLast(t=>t.branch)?.branch||'all')}</select>`)}${field('Ответ — можно поправить',area(last?.bot||'','id="example-answer" rows="8"'))}<p class="help-label">Пример повлияет на ответы после публикации. Это настройка инструкций, не дообучение модели.</p>`,'Добавить в черновик',()=>{S.config.examples.push({branch:$('#example-branch').value,rating:a==='example-good'?'good':'bad',question:last?.user||'',answer:$('#example-answer').value});changed();toast('Пример добавлен в правила LLM')})}
 else if(a==='remove-example'){S.config.examples.splice(i,1);changed();renderRules()}
 else if(a==='restore'){modal(`<h2>Вернуть версию ${E(id)} в черновик?</h2><p class="help-label">Текущий черновик будет заменён. В MAX пока останется версия ${S.published}. После проверки можно нажать «Опубликовать».</p>`,'Восстановить',async()=>{await api(`history/${id}/restore`,{revision:S.revision});await load();toast('Версия восстановлена в черновик')})}
 else if(a==='export'){const url=URL.createObjectURL(new Blob([JSON.stringify(S.config,null,2)],{type:'application/json'}));const anchor=document.createElement('a');anchor.href=url;anchor.download='tochka-opory-draft.json';anchor.click();URL.revokeObjectURL(url)}
 else if(a==='close-preview')togglePreview(false);
 else if(a==='resize-preview')resizePreview(!document.body.classList.contains('preview-full'));
 else if(a==='chat-font-up'||a==='chat-font-down')changeChatFont(a==='chat-font-up'?2:-2);
 else if(a==='reset-chat')await chat('',null,true);
 else if(a==='chat-button')await chat('',el.dataset.payload);
})});
$('#save').onclick=()=>safe(save);
$('#publish').onclick=()=>safe(async()=>{await save();modal(`<h2>Опубликовать изменения в MAX?</h2><p class="help-label">Черновик ${S.revision} станет новой версией. Новые сообщения будут обрабатываться по нему; текущий контекст диалогов сбросится. Сохранённые напоминания останутся.</p>${field('Что изменили',input('','id="publish-note" placeholder="Например: тёплое приветствие и вопросы о работе"'))}`,'Опубликовать',async()=>{const result=await api('publish',{revision:S.revision,note:$('#publish-note').value});S.published=result.published_id;status();toast('Опубликовано в MAX · версия '+S.published)})});
$('#preview-toggle').onclick=()=>togglePreview($('#preview').hidden);
$('#chat-form').onsubmit=ev=>{ev.preventDefault();const text=$('#chat-input').value.trim();if(!text)return;$('#chat-input').value='';safe(()=>chat(text))};
document.addEventListener('submit',ev=>{if(ev.target.id==='search-form'){ev.preventDefault();safe(async()=>{await save();const f=new FormData(ev.target),body=Object.fromEntries(f);for(const k of ['age','salary','experience'])body[k]=body[k]===''?null:Number(body[k]);body.housing=f.has('housing');$('#search-results').innerHTML='<div class="card">Запрашиваю «Работу России»…</div>';const r=await api('search-test',body);$('#search-results').innerHTML=`<div class="two-col"><div class="card"><h2>Что увидит пользователь</h2>${r.replies.map(m=>`<div class="bubble bot">${E(m.text)}</div>`).join('')}</div><div class="card"><h2>Как получился результат</h2>${traceHtml(r.trace)}</div></div>`})}});
window.addEventListener('beforeunload',ev=>{if(S.dirty){ev.preventDefault();ev.returnValue=''}});
safe(load);
